"""Exact-to-the-penny pricing, done in whole pennies."""
from dataclasses import dataclass
from decimal import Decimal

TAX_PERCENT = {"standard": 20, "reduced": 5, "zero": 0}


@dataclass
class QuoteLine:
    sku: str
    quantity: int
    unit: Decimal
    gross: Decimal
    discount: Decimal
    net: Decimal


@dataclass
class Quote:
    order: str
    date: object
    customer: str
    lines: list
    subtotal: Decimal
    order_discount: Decimal
    tax: Decimal
    total: Decimal


def money(pennies):
    """Decimal with two places from a whole number of pennies."""
    sign = "-" if pennies < 0 else ""
    return Decimal("%s%d.%02d" % (sign, abs(pennies) // 100, abs(pennies) % 100))


def to_pennies(amount):
    sign, digits, exponent = amount.as_tuple()
    value = int("".join(map(str, digits)) or "0")
    shift = exponent + 2
    value = value * 10 ** shift if shift >= 0 else _half_up(value, 10 ** -shift)
    return -value if sign else value


def _half_up(numerator, denominator):
    """numerator / denominator rounded to a whole number, halves up (non-negative inputs)."""
    return (2 * numerator + denominator) // (2 * denominator)


def price_order(order, catalog, quantities=None):
    """Price an order. `quantities` (sku -> qty) replaces the ordered quantities
    (lines whose quantity is 0 are left out); used for invoices."""
    items = []
    for sku, quantity in order.lines:
        if quantities is not None:
            quantity = quantities.get(sku, 0)
        if quantity > 0:
            items.append((sku, quantity))

    unit, gross, discount, net = [], [], [], []
    for sku, quantity in items:
        unit.append(to_pennies(catalog[sku].price))
        gross.append(quantity * unit[-1])
        percent = 10 if quantity >= 50 else 5 if quantity >= 10 else 0
        discount.append(_half_up(gross[-1] * percent, 100))
        net.append(gross[-1] - discount[-1])

    subtotal = sum(net)
    order_discount = _half_up(subtotal * 3, 100) if subtotal >= 50000 else 0

    # Share the order discount in proportion to the nets: floor, then largest remainder.
    shares = [order_discount * n // subtotal if subtotal else 0 for n in net]
    remainders = [order_discount * n % subtotal if subtotal else 0 for n in net]
    leftover = order_discount - sum(shares)
    for index in sorted(range(len(net)), key=lambda i: (-remainders[i], i))[:leftover]:
        shares[index] += 1

    tax = 0
    for (sku, _), n, share in zip(items, net, shares):
        tax += _half_up((n - share) * TAX_PERCENT[catalog[sku].tax], 100)

    lines = [QuoteLine(sku, quantity, money(unit[i]), money(gross[i]), money(-discount[i]), money(net[i]))
             for i, (sku, quantity) in enumerate(items)]
    return Quote(order.id, order.date, order.customer, lines, money(subtotal),
                 money(-order_discount), money(tax), money(subtotal - order_discount + tax))
